    h, w = len(input_g), len(input_g[0])

    positions = [(i, j) for i in range(h) for j in range(w) if input_g[i][j] == 5]
    if not positions:
        return input_g

    top, bot = min(p[0] for p in positions), max(p[0] for p in positions)
    left, right = min(p[1] for p in positions), max(p[1] for p in positions)

    output = [[input_g[i][j] for j in range(w)] for i in range(h)]

    r_min, r_max = top + 1, bot - 1
    c_min, c_max = left + 1, right - 1
    width = c_max - c_min + 1

    num_rows = min(r_max - r_min + 1, 7)

    for dr in range(num_rows):
        r = r_min + dr

        if dr == 0:
            # First interior row: all 2s
            for c in range(c_min, c_max + 1):
                output[r][c] = 2
        elif dr == 1 or dr == 2:
            # Rows 1-2: edges 2, middle 5
            output[r][c_min] = 2
            output[r][c_max] = 2
            for c in range(c_min + 1, c_max):
                output[r][c] = 5
        elif dr == 3 or dr == 4 or dr == 5:
            # Rows 3-5: edges 2, near-edges 5, center 0
            output[r][c_min] = 2
            output[r][c_max] = 2
            margin = max(2, (width + 2) // 4)
            for c in range(c_min + 1, c_min + margin):
                output[r][c] = 5
            for c in range(c_max - margin + 1, c_max):
                output[r][c] = 5
            for c in range(c_min + margin, c_max - margin + 1):
                output[r][c] = 0
        else:  # dr == 6 (last row for num_rows=7)
            # Last interior row: all 2s (mirrors first row)
            for c in range(c_min, c_max + 1):
                output[r][c] = 2

    return output

