import json

def solve_pattern(input_grid):
    h, w = len(input_grid), len(input_grid[0])

    positions = [(r, c) for r in range(h) for c in range(w) if input_grid[r][c] == 5]
    if not positions:
        return input_grid

    top, bot = min(p[0] for p in positions), max(p[0] for p in positions)
    left, right = min(p[1] for p in positions), max(p[1] for p in positions)

    output = [[input_grid[i][j] for j in range(w)] for i in range(h)]

    r_min, r_max = top + 1, bot - 1
    c_min, c_max = left + 1, right - 1

    num_fill = min(r_max - r_min + 1, 7)

    for dr in range(num_fill):
        r = r_min + dr

        if dr == 0 or dr == 6:
            for c in range(c_min, c_max + 1):
                output[r][c] = 2
        elif dr == 1 or dr == 5:
            for c in range(c_min, c_max + 1):
                output[r][c] = 2 if c == c_min or c == c_max else 5
        else:
            width = c_max - c_min + 1
            margin = max(2, (width + 2) // 4)

            output[r][c_min] = 2
            output[r][c_max] = 2

            for c in range(c_min + 1, c_min + margin + 1):
                output[r][c] = 5
            for c in range(c_max - margin, c_max):
                output[r][c] = 5

            for c in range(c_min + margin + 1, c_max - margin):
                output[r][c] = 0

    return output

